WITH cleaned AS (SELECT id, txn_type, amount, txn_time, merchant, is_flagged, UPPER(txn_type) AS txn_type_upper, DATEDIFF(CURRENT_DATE(), txn_time) AS days_since_txn_time, COALESCE(merchant, 'OTHER') AS merchant_clean FROM transactions WHERE txn_time > TIMESTAMP '2023-10-15 07:00:00' AND merchant = 'Lazada') SELECT id, txn_type, amount, txn_time, merchant, is_flagged, txn_type_upper, days_since_txn_time, merchant_clean, ROUND(amount / SUM(amount) OVER (PARTITION BY txn_type, merchant), 4) AS amount_share, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY days_since_txn_time, id) AS event_seq, PERCENT_RANK() OVER (PARTITION BY merchant ORDER BY amount DESC NULLS LAST) AS amount_percent_rank, FIRST_VALUE(amount, TRUE) OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount FROM cleaned;
